(* [comment removed for export] *)
Record pvals2 : Type := PV2 { pv_level : expr; pv_wend : expr; pv_wptr : expr; pv_st : expr; pv_sst : expr; pv_nst : expr; pv_more : expr; pv_done : expr; pv_size : expr;
                              pv_sb : expr; pv_send : expr; pv_scend : expr }.
Definition win_of (p e : Z) : option (Z * Z) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S10!2+3+0+0$p;R+0$e;R+0-1RN$~R+1!1+20!2'4#1,52!1,60!2,70!4,8+0+0#2#1").
Definition pview2 (cells : list kentry) (Pb pe ce : expr) : option pvals2 := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S70!1+2+<}4}8}1|800;!1,>|808;!1,6+<$cells;R!1+9+:$Pb;R+;$pe;R+;$ce;R+;-2RN$x;R!1+2+;0!4'=#4#3!1,>|710;12$lvl;R+;-2RN$x;R!1+2+;0!4'=#5#4!1,>|740;22$wend;R+;-2RN$x;R!1+2+;0!4'=#6#5!1,>|748;22$wptr;R+;-2RN$x;R!1+2+;0!4'=#7#6!1,>|750;32$st;R+;-2RN$x;R!1+2+;0!4'=#8#7!1,>|751;32$sst;R+;-2RN$x;R!1+2+;0!4'=#9#8!1,>|752;32$nst;R+;-2RN$x;R!1+2+;0!4'=#:#9!1,>|753;32$more;R+;-2RN$x;R!1+2+;0!4'=#;#:!1,>|754;32$done;R+;-2RN$x;R!1+2+;0!4'=#<#;!1,>|768;22$se;R+;-2RN$x;R!1+2+;0!4'=#=#<!1,>|778;22$csb;R+;-2RN$x;R!1+2+;0!4'=#>#=!1,>422$csend;R+;-2RN$x;R!1+2+;0!4'=#?#>522$cscend;R+;-1RN$~R+10!2'?!2'@#@#?!8'A#@#?!1,>|760;#>#=#45!1,>|J0000000;2!2,7+<!<,B#<#;#:#9#8#7#6#5#4#3#2#16666666666666").

Lemma parser_view2 : forall E (M : mem) cells Pb pe ce pv P (bm bd : bool) (stack : list Z) scap,
  know_ok RSEGS E M cells -> pview2 cells Pb pe ce = Some pv ->
  uv E Pb = P -> 2 ^ 32 <= P -> P + 272 <= 2 ^ 63 ->
  uv E (pv_more pv) = PML.b2z bm -> uv E (pv_done pv) = PML.b2z bd ->
  L5.bytes_at RSEGS M (uv E (pv_sb pv)) stack -> uv E (pv_send pv) = uv E (pv_sb pv) + Z.of_nat (length stack) -> uv E (pv_scend pv) = uv E (pv_sb pv) + scap -> Z.of_nat (length stack) <= scap ->
  uv E (pv_wptr pv) <= uv E (pv_wend pv) ->
  L5.defined M P 272 ->
  exists buf : list Z,
    PML.parser_at M P (PML.PS (uv E (pv_st pv)) (uv E (pv_sst pv)) (uv E (pv_nst pv)) bm bd (uv E (pv_level pv)) stack (uv E (pv_sb pv)) scap (uv E ce) (uv E pe) buf
